<?php require_once __DIR__.'/alumno_common.php'; $stmt=$pdo->prepare("SELECT m.nombre AS materia,m.clave,p.nombre AS profesor,g.nombre AS grupo,h.dia,h.hora_inicio,h.hora_fin,h.aula FROM inscripciones i JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia JOIN profesores p ON p.id=mp.profesor JOIN grupos g ON g.id=mp.grupo JOIN horarios h ON h.asignacion=mp.id WHERE i.alumno=? ORDER BY FIELD(h.dia,'lunes','martes','miercoles','jueves','viernes','sabado'),h.hora_inicio");$stmt->execute([$alumnoActual['id']]);$horarios=$stmt->fetchAll(); alumno_layout('Horarios','Consulta los días, horas y aulas de tus materias','horariosAlumno.html',compact('horarios'));
